 {n:'Graphites',syms:[T('پہلا حیض دیر سے','First menses late','Pehla haiz dair se'),T('موٹاپا اور سردی کی حساسیت','Obesity with chilliness','Motapa aur sardi ki hassasiyat'),T('قبض کا ساتھ','With constipation','Qabz ka sath')],mod:T('بدتر: موسم سرما، رات؛ بہتر: گرمی اور کھانے سے','Worse: winter, night; Better: warmth, eating','Badtar: mausma-e-sarma, raat; Behtar: garmi aur khanay se')},
 {n:'Calcarea Carb',syms:[T('حیض دیر سے، کمزور خواتین','Late menses in fair, weak women','Haiz dair se, kamzor khawateen'),T('سر درد اور کلف','Headache with chilliness','Sar dard aur kalf'),T('دودھ سے پیٹ خراب','Milk disagrees','Doodh se pait kharab')],mod:T('بدتر: سرد نمی، دودھ؛ بہتر: گرم خشک موسم','Worse: cold damp, milk; Better: warm dry weather','Badtar: sard nami, doodh; Behtar: garam khushk mausam')},
 {n:'Aletris',syms:[T('خون کی کمی سے حیض بند','Amenorrhea from anemia','Khoon ki kami se haiz band'),T('تھکاوٹ اور کمزوری','Fatigue and weakness','Thakawat aur kamzori'),T('ٹھنڈے پاؤں، سر چکر','Cold feet, dizziness','Thanday paon, sar chakkar')],mod:T('بدتر: محنت، کمزوری؛ بہتر: آرام اور غذا سے','Worse: exertion, weakness; Better: rest, nutrition','Badtar: mehnat, kamzori; Behtar: aaram aur ghiza se')}
